c401e71713486c119fb25db9c933\";s:148:\":root :where(.wp-block-separator){border-color: currentColor;border-width: 0 0 1px 0;border-style: solid;color: var(--wp--preset--color--accent-6);}\";s:32:\"a862ab6a78959f54fc876112c4a998bd\";s:86:\":root :where(.wp-block-site-tagline){font-size: var(--wp--preset--font-size--medium);}\";s:32:\"90eecb95bae999b175a93ef72195ee2a\";s:75:\":root :where(.wp-block-site-title){font-weight: 700;letter-spacing: -.5px;}\";s:32:\"f513d889cf971b13995cc3fffed2f39b\";s:92:\":root :where(.wp-block-site-title a:where(:not(.wp-element-button))){text-decoration: none;}\";s:32:\"22c37a317cc0ebd50155b5ad78564f37\";s:103:\":root :where(.wp-block-site-title a:where(:not(.wp-element-button)):hover){text-decoration: underline;}\";s:32:\"f2d6868602fe95da6c3ae6daa5b45483\";s:90:\":root :where(.wp-block-term-description){font-size: var(--wp--preset--font-size--medium);}\";s:32:\"1685279bb677da079f4170f16d61615e\";s:84:\":root :where(.wp-block-navigation){font-size: var(--wp--preset--font-size--medium);}\";s:32:\"25289a01850f5a0264ddb79a9a3baf3d\";s:92:\":root :where(.wp-block-navigation a:where(:not(.wp-element-button))){text-decoration: none;}\";s:32:\"026c04da08398d655a95047f1f235d97\";s:103:\":root :where(.wp-block-navigation a:where(:not(.wp-element-button)):hover){text-decoration: underline;}\";s:32:\"e83ceb73c67046422fa48272207a5b8a\";s:52:\":root :where(.wp-block-list li){margin-top: 0.5rem;}\";s:32:\"1b8b5af9cb7796418be3edaf7703509e\";s:0:\"\";s:32:\"cef4ee042e0b7007042b04963f4d208f\";s:0:\"\";s:32:\"1738cc37ebc2f9e59138eb65d9876e13\";s:0:\"\";s:32:\"8ca8b48d1d736d275874a16d2ee6a2df\";s:0:\"\";}}','on');
