INSERT INTO `wp_postmeta` VALUES (1153,225,'_wp_desired_post_slug','integritetspolicy');
INSERT INTO `wp_postmeta` VALUES (1156,229,'policy_heading','Integritetspolicy – Affärsnätverket Fenix');
INSERT INTO `wp_postmeta` VALUES (1157,229,'_policy_heading','field_6af58a501ebca');
INSERT INTO `wp_postmeta` VALUES (1158,229,'policy_intro','Affärsnätverket Fenix värnar om din personliga integritet. Denna integritetspolicy beskriver hur föreningen samlar in, använder och skyddar personuppgifter i enlighet med EU:s dataskyddsförordning (GDPR).');
INSERT INTO `wp_postmeta` VALUES (1159,229,'_policy_intro','field_6af58a71e04ce');
INSERT INTO `wp_postmeta` VALUES (1160,229,'section_heading_1','1. Personuppgiftsansvarig');
INSERT INTO `wp_postmeta` VALUES (1161,229,'_section_heading_1','field_6af58a9e28e88');
INSERT INTO `wp_postmeta` VALUES (1162,229,'section_1_content','<p>Affärsnätverket Fenix är personuppgiftsansvarig för behandling av personuppgifter inom ramen för nätverkets verksamhet.</p>');
INSERT INTO `wp_postmeta` VALUES (1163,229,'_section_1_content','field_6af58aab28e89');
INSERT INTO `wp_postmeta` VALUES (1164,229,'section_heading_2','2. Vilka personuppgifter vi behandlar');
INSERT INTO `wp_postmeta` VALUES (1165,229,'_section_heading_2','field_6af58abe28e8a');
INSERT INTO `wp_postmeta` VALUES (1166,229,'section_2_content','<p>Vi kan komma att behandla personuppgifter om <strong>medlemmar och gäster</strong>, exempelvis:</p><ul><li>Namn</li><li>Företag och roll</li><li>E-postadress</li><li>Telefonnummer</li><li>Faktureringsuppgifter</li><li>Närvaro-, gäst- och medlemsrelaterad information</li></ul>');
INSERT INTO `wp_postmeta` VALUES (1167,229,'_section_2_content','field_6af58acc28e8b');
INSERT INTO `wp_postmeta` VALUES (1168,229,'section_heading_3','3. Ändamål och laglig grund');
INSERT INTO `wp_postmeta` VALUES (1169,229,'_section_heading_3','field_6af58ad628e8c');
INSERT INTO `wp_postmeta` VALUES (1170,229,'section_3_content','<p>Personuppgifter behandlas för att:</p><ul><li>administrera medlemskap och gästbesök</li><li>hantera kommunikation, möten och aktiviteter</li><li>sköta fakturering och ekonomisk administration</li></ul><p>Behandlingen sker med stöd av avtal (medlemskap), rättslig förpliktelse samt samtycke där så krävs.</p>');
INSERT INTO `wp_postmeta` VALUES (1171,229,'_section_3_content','field_6af58ae228e8d');
INSERT INTO `wp_postmeta` VALUES (1172,229,'section_heading_4','4. Lagring och skydd');
INSERT INTO `wp_postmeta` VALUES (1173,229,'_section_heading_4','field_6af58aed28e8e');
INSERT INTO `wp_postmeta` VALUES (1174,229,'section_4_content','<p>Personuppgifter sparas endast så länge det är nödvändigt för ändamålet eller enligt lagkrav. Uppgifterna skyddas genom lämpliga tekniska och organisatoriska åtgärder.</p><h2>5. Delning av uppgifter</h2><p>Affärsnätverket Fenix säljer eller delar aldrig personuppgifter till tredje part i marknadsföringssyfte. Uppgifter kan delas med leverantörer av system eller tjänster som krävs för föreningens verksamhet, exempelvis bokföring eller IT-system.</p><h2>6. Dina rättigheter</h2><p>Du har rätt att:</p><ul><li>begära registerutdrag</li><li>begära rättelse av felaktiga uppgifter</li><li>begära radering av uppgifter där så är tillåtet</li><li>invända mot eller begära begränsning av behandling</li></ul><p>För frågor eller begäran rörande personuppgifter, kontakta föreningen.</p><h2>7. Ändringar i policyn</h2><p>Denna integritetspolicy kan uppdateras vid behov. Den senast gällande versionen finns tillgänglig via nätverkets kommunikation och formulär.</p><p>Genom att ansöka om medlemskap, anmäla sig eller delta som gäst godkänner du denna integritetspolicy och samtycker till att Affärsnätverket Fenix behandlar dina personuppgifter i enlighet med ovanstående.</p>');
INSERT INTO `wp_postmeta` VALUES (1175,229,'_section_4_content','field_6af58afc28e8f');
